import Link from "next/link";
import {CheckCircle2,Clock3,PlusCircle,Car,MessageSquare,ArrowUpRight} from "lucide-react";
import {requireUser} from "@/lib/auth";
import {connectMongoose} from "@/lib/db";
import {VendorProfileModel} from "@/models/VendorProfile";
import {VehicleModel} from "@/models/Vehicle";
import {InquiryModel} from "@/models/Inquiry";
import {VerifiedSellerBadge} from "@/components/sellers/verified-seller-badge";
export default async function Page(){const user=await requireUser("/vendor");await connectMongoose();const profile=await VendorProfileModel.findOne({userId:user.id}).select("_id status displayName").lean();if(!profile)return <section className="seller-empty"><h2>Set up your seller profile</h2><p>Complete your application before adding a vehicle.</p><Link className="btn btn-primary" href="/become-a-vendor">Start selling</Link></section>;const approved=profile.status==="APPROVED";if(!approved)return <section className="seller-status"><Clock3/><div><b>{profile.status==="PENDING"?"Application under review":profile.status==="REJECTED"?"Your seller profile needs attention":"Seller account suspended"}</b><p>{profile.status==="PENDING"?"We’re reviewing your seller profile. You can browse the marketplace while you wait.":"Visit your seller application for the current status and next steps."}</p></div><Link className="btn btn-light" href="/become-a-vendor">View application</Link></section>;const[active,pending,inquiries,recent]=await Promise.all([VehicleModel.countDocuments({vendorId:profile._id,status:"ACTIVE"}),VehicleModel.countDocuments({vendorId:profile._id,status:"PENDING_REVIEW"}),InquiryModel.countDocuments({vendorId:String(profile._id),status:{$ne:"CLOSED"}}),VehicleModel.find({vendorId:profile._id}).sort({createdAt:-1}).limit(3).select("title status price slug").lean()]);return <><section className="seller-welcome"><div><p className="eyebrow">OVERVIEW</p><h2>Manage cars with clarity.</h2><p>Keep listings current, respond to buyers, and move your next car forward.</p><div className="mt-5 flex flex-wrap gap-3"><Link href="/vendor/cars/new" className="btn btn-dark"><PlusCircle size={17}/>List a new car</Link><Link href="/vendor/cars" className="btn btn-light">Manage listings</Link></div></div><div className="seller-verified"><CheckCircle2/><div><b>{profile.displayName}</b><VerifiedSellerBadge/><small>Approved CarXSailor seller</small></div></div></section><section className="seller-metrics"><article><span>Active listings</span><b>{active}</b><small>Visible to buyers</small></article><article><span>Under review</span><b>{pending}</b><small>Awaiting approval</small></article><article><span>Open messages</span><b>{inquiries}</b><small>Buyer conversations</small></article></section><section className="seller-recent"><div className="seller-section-heading"><div><p className="eyebrow">YOUR INVENTORY</p><h2>Recent listings</h2></div><Link href="/vendor/cars">View all <ArrowUpRight size={16}/></Link></div>{recent.length?<div className="seller-list">{recent.map(car=><Link href={`/vendor/cars/${car._id}`} key={String(car._id)}><div className="seller-car-icon"><Car size={19}/></div><div><b>{car.title}</b><p>{car.status.replaceAll("_"," ")}</p></div><span>₦{car.price.toLocaleString("en-NG")}</span><ArrowUpRight size={18}/></Link>)}</div>:<div className="seller-empty"><Car/><h3>Your inventory starts here</h3><p>Add a car, photos, and a selling price to submit it for review.</p><Link className="btn btn-dark" href="/vendor/cars/new">List your first car</Link></div>}</section></>}
